let mainView='summary',expenseContext=null,expensePaymentContext=null;
function rentItems(){return [['rent-room-1','Sala 1 — aluguel base (4 posições)',380000],['rent-room-1-extra-1','Sala 1 — posição adicional 1',70000],['rent-room-1-extra-2','Sala 1 — posição adicional 2',70000],['rent-room-1-extra-3','Sala 1 — posição adicional 3',70000],['rent-room-2','Sala 2 — aluguel base (4 posições)',380000]].map(([id,name,amount])=>({id,name,kind:'fixed',amount,date:null,paidDate:null,voided:false}));}
function serviceHoursItem(){return {id:'service-hours-20',name:'Horas de atendimento — pacote de 20 horas',kind:'fixed',amount:100000,date:null,paidDate:null,fees:0,voided:false};}
function seedServiceHours(){if(state.serviceHoursSeeded)return;const c=companyMonth('2026-10');if(!c.items.some(e=>e.id==='service-hours-20')){const lastRent=c.items.reduce((last,e,i)=>e.id.startsWith('rent-room-')?i:last,-1);c.items.splice(lastRent+1,0,serviceHoursItem());}state.serviceHoursSeeded=true;}
function marketingItems(month){return [14,28].map(day=>({id:'marketing-'+day,name:'Marketing — parcela dia '+day,kind:'fixed',amount:50000,date:month+'-'+day,paidDate:null,fees:0,voided:false}));}
function seedMarketing(){if(state.marketingSplitSeeded)return;const c=companyMonth('2026-10');c.items=c.items.filter(e=>{if(e.kind!=='fixed'||e.name!=='Marketing')return true;if(e.amount===null&&!e.date&&!e.paidDate)return false;e.name='Marketing — registro anterior ao parcelamento';e.voided=true;return true;});for(const e of marketingItems('2026-10'))if(!c.items.some(x=>x.id===e.id))c.items.push(e);state.marketingSplitSeeded=true;}
function expenseToday(){return new Intl.DateTimeFormat('sv-SE',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());}
function expenseStatus(e,today=expenseToday()){if(e.voided)return 'Excluído';if(e.kind!=='fixed')return e.paidDate?'Pago':'Pendente';if(!e.date)return e.paidDate?'Pago · sem vencimento':'Vencimento a preencher';const days=Math.round((Date.parse((e.paidDate||today)+'T12:00:00Z')-Date.parse(e.date+'T12:00:00Z'))/86400000);return e.paidDate?(days>0?'Pago com '+days+' dia(s) de atraso':'Pago no prazo'):(days>0?'Vencido há '+days+' dia(s)':days===0?'Vence hoje':'A vencer');}
function fixedExpenseTable(list){const date=d=>d?d.split('-').reverse().join('/'):'—';return `<div class="expense-table-wrap"><table class="expense-table"><thead><tr><th>Gasto</th><th>Valor</th><th>Vencimento</th><th>Pagamento</th><th>Situação</th><th>Multa / juros</th><th>Ações</th></tr></thead><tbody>${list.map(e=>`<tr class="${e.voided?'voided':''}"><td>${esc(e.name)}</td><td>${e.amount===null?'—':money(e.amount/100)}</td><td>${date(e.date)}</td><td>${date(e.paidDate)}</td><td>${expenseStatus(e)}</td><td>${money((e.fees||0)/100)}</td><td><div class="expense-actions">${!e.voided?`<button data-expense-pay="${esc(e.id)}" ${e.amount===null?'disabled':''}>${e.paidDate?'Editar pagamento':'Marcar pago'}</button>`:''}<button data-expense-edit="${esc(e.id)}">Editar gasto</button><button data-expense-void="${esc(e.id)}">${e.voided?'Restaurar':'Excluir'}</button></div></td></tr>`).join('')}</tbody></table></div><p class="hint">Atraso calculado por dias corridos. Multas e juros são informados por você; não há cobrança automática.</p>`;}
function openExpensePayment(id){const e=companyMonth().items.find(x=>x.id===id);if(!e||e.voided||e.amount===null)return;expensePaymentContext={month:$('#month').value,id};const f=$('#expense-payment-form');f.reset();$('#expense-payment-name').textContent=e.name+' · '+money(e.amount/100);f.elements.paidDate.value=e.paidDate||expenseToday();f.elements.fees.value=formatCredit(e.fees||0);$('#unpay-expense').hidden=!e.paidDate;$('#expense-payment-dialog').showModal();}
document.querySelector('#close-expense-payment').onclick=()=>$('#expense-payment-dialog').close();
document.querySelector('#expense-payment-form').onsubmit=ev=>{ev.preventDefault();const f=ev.target;if(!f.reportValidity()||!expensePaymentContext)return;const date=f.elements.paidDate.value;if(!validDate(date)||date>expenseToday()){toast('Informe a data em que o pagamento ocorreu, até hoje.');return;}const e=companyMonth(expensePaymentContext.month).items.find(x=>x.id===expensePaymentContext.id);e.paidDate=date;e.fees=parseCredit(f.elements.fees.value);save();render();$('#expense-payment-dialog').close();toast('Pagamento registrado com data');};
document.querySelector('#unpay-expense').onclick=()=>{const e=companyMonth(expensePaymentContext.month).items.find(x=>x.id===expensePaymentContext.id);e.paidDate=null;e.fees=0;save();render();$('#expense-payment-dialog').close();toast('Pagamento desmarcado e encargos removidos');};
function companyMonth(month=$('#month').value){state.company??={};return state.company[month]??(state.company[month]={revenue:null,items:[...(month>='2026-10'?[...rentItems(),serviceHoursItem()]:[{id:'fixed-0',name:'Aluguel',kind:'fixed',amount:null,date:null,paidDate:null,voided:false}]),...(month>='2026-10'?marketingItems(month):[{id:'fixed-1',name:'Marketing',kind:'fixed',amount:null,date:null,paidDate:null,voided:false}]),{id:'fixed-2',name:'Pós-venda',kind:'fixed',amount:null,date:null,paidDate:null,voided:false}]});}
function seedRentDetails(){if(state.rentDetailsSeeded)return;const c=companyMonth('2026-10');c.items=c.items.filter(e=>{if(e.kind!=='fixed'||e.name!=='Aluguel')return true;if(e.amount===null&&!e.date&&!e.paidDate)return false;e.voided=true;e.name='Aluguel — registro anterior ao detalhamento';return true;});const newItems=rentItems();for(const item of newItems)if(!c.items.some(e=>e.id===item.id))c.items.push(item);state.rentDetailsSeeded=true;}
function companyTotals(month=$('#month').value){const c=companyMonth(month),active=c.items.filter(e=>!e.voided),sum=list=>list.reduce((s,e)=>s+(e.amount||0)+(e.fees||0),0),fixed=sum(active.filter(e=>e.kind==='fixed')),variable=sum(active.filter(e=>e.kind==='variable')),paid=sum(active.filter(e=>e.paidDate)),pending=sum(active.filter(e=>!e.paidDate));let vt=0,vtPaid=0,vtPayments=0,commission=0;for(const person of state.people){const r=state.records[month+':'+person.id];if(!r)continue;prepare(r,month);for(const payment of r.transfers){if(!payment.voided){vtPaid+=payment.amount;vtPayments++;}}vt+=Object.values(r.costs).reduce((s,n)=>s+n,0);commission+=r.settlement?.gross??cents(r.commission);}const expense=paid+pending,revenue=companySalesRevenue(month),taxRate=c.taxRate??20,tax=Math.round(revenue*Math.round(taxRate*100)/10000);return {revenue,taxRate,tax,fixed,variable,expense,paid,pending,vt,vtPaid,vtPayments,commission,profit:revenue-expense-vt-commission-tax,incomplete:active.filter(e=>e.amount===null||!e.date).length};}
function expenseCards(kind){const c=companyMonth(),list=c.items.filter(e=>e.kind===kind);if(kind==='fixed')return fixedExpenseTable(list);return list.map(e=>`<article class="expense-item ${e.voided?'voided':''}"><div><h3>${esc(e.name)}</h3><p>${e.date?`${kind==='fixed'?'Vencimento':'Compra'}: ${e.date.split('-').reverse().join('/')}`:'Data a preencher'}</p><small>${e.voided?'Excluído':e.paidDate?'Pago em '+e.paidDate.split('-').reverse().join('/'):e.amount===null?'Valor a preencher':'Pendente'}</small></div><div class="expense-value"><strong>${e.amount===null?'—':money(e.amount/100)}</strong><div><button data-expense-edit="${esc(e.id)}">Editar</button><button data-expense-void="${esc(e.id)}">${e.voided?'Restaurar':'Excluir'}</button></div></div></article>`).join('')||'<p class="hint">Nenhuma compra registrada neste mês.</p>';}
function renderCompany(){const c=companyMonth(),t=companyTotals();$('#stats').innerHTML=[['Gastos da empresa',t.expense,'Fixos + variados'],['Fixos do mês',t.fixed,'Aluguel, atendimento, marketing e pós-venda'],['Variados do mês',t.variable,'Compras e materiais'],['Gastos pendentes',t.pending,'Ainda sem data de pagamento']].map(([label,value,note])=>`<div class="stat"><span class="stat-label">${label}</span><strong>${money(value/100)}</strong><small>${note}</small></div>`).join('');$('#company-section').innerHTML=`<div class="section-head"><div><span class="eyebrow">EMPRESA</span><h2>Gastos do mês</h2><p>Contas fixas e compras do dia a dia.</p></div></div><div class="expense-columns"><section><div class="week-top"><h3>Mensais fixos</h3><button class="primary" id="add-fixed-expense">＋ Adicionar gasto mensal</button><button id="copy-fixed">Copiar mês anterior</button></div><p class="hint">Defina o valor e o vencimento de cada conta.</p>${expenseCards('fixed')}</section><section><div class="week-top"><h3>Variados</h3><button class="primary" id="add-expense">＋ Adicionar gasto</button></div><div class="expense-suggestions">${['Folha de sulfite','Material de escritório','Tinta de impressão'].map(name=>`<button data-expense-suggestion="${name}">＋ ${name}</button>`).join('')}</div><article class="team-vt-total"><div class="week-top"><h3>Vale-transporte de toda a equipe</h3><span class="badge">AUTOMÁTICO</span></div><span class="eyebrow">TOTAL PAGO EM VT</span><strong class="team-vt-amount">${money(t.vtPaid/100)}</strong><p>${t.vtPayments} pagamento(s) registrado(s) nas semanas do mês selecionado.</p><p class="hint">Soma automática dos pagamentos de todos os vendedores. Pagamentos cancelados não entram. Para consultar ou alterar um lançamento, abra o vendedor.</p><div class="week-top"><span>VT utilizado nas presenças confirmadas</span><strong>${money(t.vt/100)}</strong></div><p class="hint">O lucro considera o VT utilizado uma única vez. O total pago pode incluir adiantamentos para dias ainda não utilizados. Não cadastre esse total novamente como gasto manual.</p><button data-main-view="team">Ver vendedores</button></article>${expenseCards('variable')}</section></div><section class="profit-panel"><div><h3>Resultado estimado do mês</h3><p class="hint">Informe a receita da empresa, não o volume total das vendas.</p></div><label>Receita da empresa no mês (R$)<input id="company-revenue" type="text" inputmode="decimal" data-money autocomplete="off" data-money-min="0" data-money-max="1000000000000" placeholder="Informe a receita" value="${c.revenue===null?'':formatCredit(c.revenue)}"></label><label class="tax-input">Imposto sobre o faturamento (%)<input id="company-tax-rate" type="number" min="0" max="100" step="0.01" required value="${t.taxRate}"></label><p class="hint">Percentual aplicado à receita da empresa neste mês. Padrão de 20%, editável. Alterar um mês não altera os demais.</p><dl class="ledger"><div><dt>Receita informada</dt><dd>${c.revenue===null?'Não informada':money(c.revenue/100)}</dd></div><div><dt>Imposto sobre o faturamento (${t.taxRate.toLocaleString('pt-BR')}%)</dt><dd>${t.tax===null?'Informe a receita':'− '+money(t.tax/100)}</dd></div><div><dt>Gastos fixos e variados</dt><dd>− ${money(t.expense/100)}</dd></div><div><dt>Comissões brutas dos vendedores</dt><dd>− ${money(t.commission/100)}</dd></div><div><dt>VT utilizado (presenças confirmadas)</dt><dd>− ${money(t.vt/100)}</dd></div></dl><div class="profit-result"><span>${t.profit===null?'Resultado a calcular':t.profit<0?'Prejuízo estimado':'Lucro estimado'}</span><strong>${t.profit===null?'Informe a receita':money(t.profit/100)}</strong></div><p class="hint">Multas e juros registrados estão incluídos nos gastos. ${t.incomplete?`${t.incomplete} conta(s) com valor ou data a preencher. `:''}Estimativa com os lançamentos registrados, incluindo contas pendentes. Vales recuperáveis não são descontados novamente: a comissão bruta já está incluída. Inclui o imposto calculado pelo percentual informado. Outros custos não cadastrados não entram na estimativa.</p></section>`;}
const renderCompanyTotal=renderCompany;
renderCompany=function(){renderCompanyTotal();const panel=document.querySelector('#company-section .profit-panel');if(!panel)return;panel.classList.add('revenue-settings');panel.querySelector('h3').textContent='Imposto do resumo';panel.querySelector('div>.hint').textContent='O faturamento é calculado automaticamente pelas vendas do mês.';panel.querySelector('label:has(#company-revenue)')?.remove();panel.querySelector('.ledger')?.remove();panel.querySelector('.profit-result')?.remove();panel.querySelectorAll(':scope>p').forEach(element=>element.remove());};
const renderCompanyBreakdown=renderCompany;
let companyExpenseTab='fixed';
renderCompany=function(){renderCompanyBreakdown();const columns=$('#company-section .expense-columns');if(!columns)return;columns.classList.add('expense-tabbed');const sections=[...columns.children];sections.forEach((section,index)=>{const key=index===0?'fixed':'variable';section.dataset.expensePanel=key;section.hidden=key!==companyExpenseTab;});const tabs=document.createElement('div');tabs.className='company-expense-tabs';tabs.setAttribute('role','tablist');tabs.setAttribute('aria-label','Tipos de gastos');tabs.innerHTML=`<button type="button" role="tab" data-company-expense-tab="fixed" aria-selected="${companyExpenseTab==='fixed'}" class="${companyExpenseTab==='fixed'?'selected':''}">Mensais fixos</button><button type="button" role="tab" data-company-expense-tab="variable" aria-selected="${companyExpenseTab==='variable'}" class="${companyExpenseTab==='variable'?'selected':''}">Variados</button>`;columns.before(tabs);};
function compactTeamVT(t){return `<div class="team-vt-line"><strong>Vale-transporte da equipe</strong><span>Pago <b>${money(t.vtPaid/100)}</b></span><span>Utilizado <b>${money(t.vt/100)}</b></span><span>Não utilizado <b>${money(Math.max(0,t.vtPaid-t.vt)/100)}</b></span></div>`;}
const renderCompanyTabbed=renderCompany;
renderCompany=function(){renderCompanyTabbed();const card=document.querySelector('#company-section .team-vt-total');if(card)card.outerHTML=compactTeamVT(companyTotals());};
let fixedExpenseFilter='all',fixedExpenseSearch='',variableExpenseFilter='all',variableExpenseSearch='';
function fixedExpenseState(e,today=expenseToday()){if(e.paidDate)return {label:!e.date?'Pago sem vencimento':expenseStatus(e,today),tone:'paid'};if(!e.date)return {label:'Vencimento não preenchido',tone:'missing'};if(e.date===today)return {label:'Vence hoje',tone:'today'};if(e.date<today)return {label:expenseStatus(e,today),tone:'overdue'};return {label:'A vencer',tone:'future'};}
function fixedExpenseSummary(list,today=expenseToday()){const active=list.filter(e=>!e.voided),valued=active.filter(e=>e.amount!==null),total=valued.reduce((n,e)=>n+e.amount+(e.fees||0),0),paidEntries=valued.filter(e=>e.paidDate),openEntries=valued.filter(e=>!e.paidDate),overdueEntries=openEntries.filter(e=>e.date&&e.date<today);return {all:active.length,paidCount:active.filter(e=>e.paidDate).length,openCount:active.filter(e=>!e.paidDate).length,missing:active.filter(e=>e.amount===null).length,total,paid:paidEntries.reduce((n,e)=>n+e.amount+(e.fees||0),0),open:openEntries.reduce((n,e)=>n+e.amount+(e.fees||0),0),overdue:overdueEntries.reduce((n,e)=>n+e.amount+(e.fees||0),0),overdueCount:overdueEntries.length};}
function fixedExpenseSummaryCards(summary){const card=(label,value,note,tone)=>`<div class="stat expense-stat ${tone}"><span class="stat-label">${label}</span><strong>${money(value/100)}</strong><small>${note}</small></div>`;return card('Total cadastrado',summary.total,summary.missing?summary.missing+' gasto(s) sem valor':'Todos os valores preenchidos','total')+card('Pago',summary.paid,summary.paidCount+' pagamento(s)','paid')+card('Em aberto',summary.open,summary.openCount+' gasto(s) pendente(s)','open')+card('Vencido',summary.overdue,summary.overdueCount+' conta(s) em atraso','overdue');}
function fixedExpenseRows(list){const date=d=>d?d.split('-').reverse().join('/'):'—';return list.map(e=>{const status=fixedExpenseState(e);return `<tr><td data-label="Gasto"><strong>${esc(e.name)}</strong>${e.amount===null?'<small>Valor pendente</small>':''}</td><td data-label="Valor">${e.amount===null?'—':money(e.amount/100)}</td><td data-label="Vencimento">${date(e.date)}</td><td data-label="Pagamento">${date(e.paidDate)}</td><td data-label="Situação"><span class="expense-status ${status.tone}">${esc(status.label)}</span></td><td data-label="Multa / juros">${money((e.fees||0)/100)}</td><td data-label="Ações"><div class="expense-actions-modern"><button data-expense-pay="${esc(e.id)}" ${e.amount===null?'disabled':''}>${e.paidDate?'Ver pagamento':'Marcar pago'}</button><details class="expense-menu"><summary aria-label="Mais ações">…</summary><div><button data-expense-edit="${esc(e.id)}">Editar gasto</button>${e.paidDate?`<button data-expense-pay="${esc(e.id)}">Editar pagamento</button>`:''}<button class="danger" data-expense-void="${esc(e.id)}">Excluir</button></div></details></div></td></tr>`;}).join('');}
function fixedExpenseDashboard(){const all=companyMonth().items.filter(e=>e.kind==='fixed'&&!e.voided),summary=fixedExpenseSummary(all),query=fixedExpenseSearch.trim().toLocaleLowerCase('pt-BR'),filtered=all.filter(e=>(fixedExpenseFilter==='paid'?!!e.paidDate:fixedExpenseFilter==='open'?!e.paidDate:true)&&(!query||e.name.toLocaleLowerCase('pt-BR').includes(query))),month=$('#month').value;return `<div class="monthly-expenses"><div class="monthly-expenses-head"><div class="fixed-tabs-slot"></div><div class="monthly-expense-actions"><label class="month-control">Mês<input type="month" id="fixed-expense-month" value="${month}"></label><button class="primary" id="add-fixed-expense">＋ Adicionar gasto</button></div></div><div class="monthly-expense-tools"><div class="expense-filter-tabs"><button data-fixed-filter="all" class="${fixedExpenseFilter==='all'?'selected':''}">Todos <span>${summary.all}</span></button><button data-fixed-filter="open" class="${fixedExpenseFilter==='open'?'selected':''}">Em aberto <span>${summary.openCount}</span></button><button data-fixed-filter="paid" class="${fixedExpenseFilter==='paid'?'selected':''}">Pagos <span>${summary.paidCount}</span></button></div><label class="expense-search">Buscar gasto<input id="fixed-expense-search" type="search" placeholder="Buscar gasto..." value="${esc(fixedExpenseSearch)}"></label></div><div class="expense-table-wrap modern"><table class="expense-table modern"><thead><tr><th>Gasto</th><th>Valor</th><th>Vencimento</th><th>Pagamento</th><th>Situação</th><th>Multa / juros</th><th>Ações</th></tr></thead><tbody>${filtered.length?fixedExpenseRows(filtered):'<tr><td colspan="7" class="expense-empty">Nenhum gasto encontrado.</td></tr>'}</tbody></table></div>${summary.missing?`<p class="monthly-expense-alert">Preencha o valor de ${summary.missing} gasto(s) pendente(s). Eles não foram tratados como zero nos totais.</p>`:''}</div>`;}
const renderCompanyCompactVT=renderCompany;
renderCompany=function(){renderCompanyCompactVT();if(companyExpenseTab!=='fixed')return;const section=document.querySelector('[data-expense-panel="fixed"]');if(!section)return;section.innerHTML=fixedExpenseDashboard();const summary=fixedExpenseSummary(companyMonth().items.filter(e=>e.kind==='fixed'&&!e.voided));$('#stats').innerHTML=fixedExpenseSummaryCards(summary);};
function variableExpenseRows(list){const date=d=>d?d.split('-').reverse().join('/'):'—';return list.map(e=>`<tr><td data-label="Descrição"><strong>${esc(e.name)}</strong>${e.amount===null?'<small>Valor pendente</small>':''}</td><td data-label="Data da compra">${date(e.date)}</td><td data-label="Data do pagamento">${date(e.paidDate)}</td><td data-label="Valor">${e.amount===null?'—':money(e.amount/100)}</td><td data-label="Ações"><div class="variable-expense-actions"><button data-expense-edit="${esc(e.id)}"><span aria-hidden="true">✎</span> Editar</button><details class="expense-menu"><summary aria-label="Mais ações">…</summary><div><button class="danger" data-expense-void="${esc(e.id)}">Excluir</button></div></details></div></td></tr>`).join('');}
function variableExpenseDashboard(){const totals=companyTotals(),all=companyMonth().items.filter(e=>e.kind==='variable'&&!e.voided),query=variableExpenseSearch.trim().toLocaleLowerCase('pt-BR'),filtered=all.filter(e=>(variableExpenseFilter==='paid'?!!e.paidDate:variableExpenseFilter==='open'?!e.paidDate:true)&&(!query||e.name.toLocaleLowerCase('pt-BR').includes(query))),unused=Math.max(0,totals.vtPaid-totals.vt),percent=totals.vtPaid>0?Math.min(100,Math.max(0,totals.vt/totals.vtPaid*100)):0;return `<div class="variable-expenses"><div class="variable-expenses-head"><div><h2>Gastos variados</h2><p>Acompanhe compras e despesas pontuais da empresa.</p></div><button class="primary" id="add-expense">＋ Adicionar gasto</button></div><div class="variable-tabs-slot"></div><article class="variable-vt-card"><div class="variable-vt-title"><span class="variable-vt-icon" aria-hidden="true">▣</span><div><h3>Vale-transporte da equipe</h3><p>Resumo de utilização</p></div></div><div class="variable-vt-metrics"><div><span>Pago</span><strong>${money(totals.vtPaid/100)}</strong></div><div><span>Utilizado</span><strong>${money(totals.vt/100)}</strong></div><div><span>Não utilizado</span><strong>${money(unused/100)}</strong></div><div class="variable-vt-progress"><i style="width:${percent.toFixed(2)}%"></i></div><small>${percent.toLocaleString('pt-BR',{maximumFractionDigits:1})}% utilizado</small></div></article><div class="variable-quick"><strong>Adicionar rapidamente</strong><div>${['Folha de sulfite','Material de escritório','Tinta de impressão'].map(name=>`<button data-expense-suggestion="${name}">＋ ${name}</button>`).join('')}</div></div><section class="variable-list-card"><div class="variable-list-head"><h3>Despesas cadastradas</h3><div><label class="expense-search">Buscar gasto<input id="variable-expense-search" type="search" placeholder="Buscar gasto..." value="${esc(variableExpenseSearch)}"></label><label class="variable-filter">Filtrar<select id="variable-expense-filter"><option value="all" ${variableExpenseFilter==='all'?'selected':''}>Todos</option><option value="open" ${variableExpenseFilter==='open'?'selected':''}>Sem pagamento</option><option value="paid" ${variableExpenseFilter==='paid'?'selected':''}>Com pagamento</option></select></label></div></div><div class="expense-table-wrap variable-modern"><table class="expense-table variable-modern"><thead><tr><th>Descrição</th><th>Valor</th><th>Data da compra</th><th>Vencimento</th><th>Pagamento</th><th>Ações</th></tr></thead><tbody>${filtered.length?variableExpenseRows(filtered):'<tr><td colspan="6" class="expense-empty">Nenhum gasto encontrado.</td></tr>'}</tbody></table></div></section></div>`;}
const renderCompanyFixedDashboard=renderCompany;
renderCompany=function(){renderCompanyFixedDashboard();document.querySelector('#company-section > .section-head')?.remove();const section=document.querySelector(`[data-expense-panel="${companyExpenseTab}"]`);if(!section)return;if(companyExpenseTab==='variable')section.innerHTML=variableExpenseDashboard();const slot=section.querySelector(companyExpenseTab==='fixed'?'.fixed-tabs-slot':'.variable-tabs-slot');if(!slot)return;document.querySelectorAll('#company-section .company-expense-tabs').forEach(tabs=>tabs.remove());slot.outerHTML=`<div class="company-expense-tabs" role="tablist" aria-label="Tipos de gastos"><button type="button" role="tab" data-company-expense-tab="fixed" aria-selected="${companyExpenseTab==='fixed'}" class="${companyExpenseTab==='fixed'?'selected':''}">Mensais fixos</button><button type="button" role="tab" data-company-expense-tab="variable" aria-selected="${companyExpenseTab==='variable'}" class="${companyExpenseTab==='variable'?'selected':''}">Variados</button></div>`;};
function switchMainView(view){mainView=view;render();}
function openExpense(id=null,name='',kind='variable'){const c=companyMonth(),entry=c.items.find(e=>e.id===id),f=$('#expense-form');expenseContext={month:$('#month').value,id,kind:entry?.kind||kind};f.reset();$('#expense-title').textContent=entry?.kind==='fixed'?'Editar gasto fixo':entry?'Editar gasto':kind==='fixed'?'Adicionar gasto mensal':'Adicionar gasto variado';f.elements.name.value=entry?.name||name;f.elements.amount.value=entry?.amount===null||!entry?'':formatCredit(entry.amount);f.elements.date.value=entry?.date||'';f.elements.paidDate.value=entry?.paidDate||'';$('#expense-date-label').textContent=expenseContext.kind==='fixed'?'Data de vencimento':'Data da compra';$('#expense-dialog').showModal();}
function copyFixed(){const [y,m]=$('#month').value.split('-').map(Number),previous=m===1?(y-1)+'-12':y+'-'+String(m-1).padStart(2,'0'),old=state.company?.[previous];if(!old){toast('Não há gastos do mês anterior para copiar.');return;}const c=companyMonth(),days=new Date(y,m,0).getDate();let copied=0;for(const item of c.items.filter(e=>e.kind==='fixed'&&!e.voided)){const source=old.items.find(e=>e.kind==='fixed'&&e.name===item.name&&!e.voided);if(source&&(item.amount===null||item.amount===source.amount)&&!item.date&&source.amount!==null&&source.date){item.amount=source.amount;item.date=$('#month').value+'-'+String(Math.min(days,Number(source.date.slice(8)))).padStart(2,'0');item.paidDate=null;copied++;}}save();render();toast(copied?`${copied} gasto(s) copiado(s), com vencimentos ajustados.`:'Nenhum gasto em branco para copiar.');}
function validateCompany(s){if(s.company===undefined)return;if(!s.company||typeof s.company!=='object'||Array.isArray(s.company))throw Error('Gastos inválidos');for(const [month,c] of Object.entries(s.company)){if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(month)||!c||!(c.revenue===null||Number.isSafeInteger(c.revenue)&&c.revenue>=0)||!(c.taxRate===undefined||Number.isFinite(c.taxRate)&&c.taxRate>=0&&c.taxRate<=100)||!Array.isArray(c.items))throw Error('Mês inválido');const ids=new Set();for(const e of c.items){const dateIsValid=e&&(e.date===null||validDate(e.date)&&(e.kind==='variable'||e.date.slice(0,7)===month)),dueDateIsValid=e&&(e.dueDate===undefined||e.dueDate===null||validDate(e.dueDate));if(!e||typeof e.id!=='string'||!e.id||ids.has(e.id)||typeof e.name!=='string'||!e.name.trim()||!['fixed','variable'].includes(e.kind)||!(e.amount===null||Number.isSafeInteger(e.amount)&&e.amount>=0)||!dateIsValid||!dueDateIsValid||!(e.paidDate===null||validDate(e.paidDate))||typeof e.voided!=='boolean'||!(e.fees===undefined||Number.isSafeInteger(e.fees)&&e.fees>=0))throw Error('Gasto inválido');ids.add(e.id);}}}
document.querySelector('#close-expense').onclick=()=>$('#expense-dialog').close();
document.querySelector('#expense-form').onsubmit=e=>{e.preventDefault();const f=e.target;if(!f.reportValidity()||!expenseContext)return;const ctx=expenseContext,date=f.elements.date.value,paidDate=f.elements.paidDate.value||null,name=f.elements.name.value.trim();if(!name||!validDate(date)||(paidDate&&!validDate(paidDate)))return;if(date.slice(0,7)!==ctx.month){toast('Escolha uma data dentro do mês selecionado. Para outro mês, altere o período no topo.');return;}const c=companyMonth(ctx.month),prior=c.items.find(e=>e.id===ctx.id),entry={id:ctx.id||crypto.randomUUID(),kind:prior?.kind||ctx.kind||'variable',name,amount:parseCredit(f.elements.amount.value),date,paidDate,fees:paidDate?(prior?.fees||0):0,voided:false};if(prior)Object.assign(prior,entry);else c.items.push(entry);save();render();$('#expense-dialog').close();toast('Gasto salvo');};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.mainView)switchMainView(b.dataset.mainView);if(b.id==='add-fixed-expense')openExpense(null,'','fixed');if(b.id==='add-expense')openExpense();if(b.dataset.expenseSuggestion)openExpense(null,b.dataset.expenseSuggestion);if(b.dataset.expenseEdit)openExpense(b.dataset.expenseEdit);if(b.dataset.expenseVoid){const item=companyMonth().items.find(e=>e.id===b.dataset.expenseVoid);if(item&&!item.voided&&!confirm('Excluir o gasto “'+item.name+'”?'))return;if(item){item.voided=!item.voided;save();render();}}if(b.dataset.expensePay)openExpensePayment(b.dataset.expensePay);if(b.id==='copy-fixed')copyFixed();});
document.addEventListener('click',e=>{const button=e.target.closest('[data-company-expense-tab]');if(!button)return;companyExpenseTab=button.dataset.companyExpenseTab;renderCompany();});
document.addEventListener('click',e=>{const button=e.target.closest('[data-fixed-filter]');if(!button)return;fixedExpenseFilter=button.dataset.fixedFilter;renderCompany();});
document.addEventListener('input',e=>{if(e.target.id!=='fixed-expense-search')return;fixedExpenseSearch=e.target.value;renderCompany();const input=$('#fixed-expense-search');input?.focus();if(input)input.setSelectionRange(input.value.length,input.value.length);});
document.addEventListener('input',e=>{if(e.target.id!=='variable-expense-search')return;variableExpenseSearch=e.target.value;renderCompany();const input=$('#variable-expense-search');input?.focus();if(input)input.setSelectionRange(input.value.length,input.value.length);});
document.addEventListener('change',e=>{if(e.target.id!=='variable-expense-filter')return;variableExpenseFilter=e.target.value;renderCompany();});
document.addEventListener('change',e=>{if(e.target.id!=='fixed-expense-month')return;if(/^\d{4}-\d{2}$/.test(e.target.value)){$('#month').value=e.target.value;render();}});
document.addEventListener('change',e=>{if(e.target.id!=='company-tax-rate')return;const t=e.target;if(!t.checkValidity()||t.value===''){t.reportValidity();return;}companyMonth().taxRate=Math.round(Number(t.value)*100)/100;save();render();});
